#include <string>
#include <cassert>

std::string get_welcome_message(const std::string &username) {
    return "Welcome, " + username + "!";
}

int main() {
    // Test case 1: Normal usage
    std::string result = get_welcome_message("test_user");
    assert(result == "Welcome, test_user!");

    // Test case 2: Empty username
    std::string empty_result = get_welcome_message("");
    assert(empty_result == "Welcome, !");

    return 0;
}

